function void AesCore :: MixColumn(ref word8 a[4][`MAXBC]);
	// The byte of every column are mixed in a linear way
	// Equation is
	// 2 3 1 1 * a0
	// 1 2 3 1	 a1
	// 1 1 2 3   a2
	// 3 1 1 2   a3
	word8 res [4][`MAXBC];

	int i, j;

	for(j = 0; j < BC; j++) begin
		for (i = 0; i < 4; i++)	begin
			res[i][j] = mul(2, a[i][j])
				^ mul(3, a[(i+1) % 4][j])
				^ a[(i + 2) % 4][j]
				^ a[(i + 3) % 4][j];
		end
	end

	for(i = 0; i < 4; i++) begin
		for( j = 0; j < 4; j++) begin
			a[i][j] = res[i][j];
		end
	end

endfunction : MixColumn

function void AesCore :: InvMixColumn(ref word8 a[4][`MAXBC]);
	// Decryption MixColumn
	// Equation is
	// 0x0e 0x0b 0x0d 0x09 * a0
	// 0x09 0x0e 0x0b 0x0d	 a1
	// 0x0d 0x09 0x0e 0x0b   a2
	// 0x0b 0x0d 0x09 0x0e   a3
	word8 res [4][`MAXBC];
	int i, j;

	for(j = 0; j < BC; j++) begin
		for (i = 0; i < 4; i++)	begin
			res[i][j] = mul(8'h0E, a[i][j])
				^ mul(8'h0B, a[(i+1) % 4][j])
				^ mul(8'h0D, a[(i+2) % 4][j])
				^ mul(8'h09, a[(i+3) % 4][j]);
		end
	end

	for(i = 0; i < 4; i++) begin
		for( j = 0; j < 4; j++) begin
			a[i][j] = res[i][j];
		end
	end

endfunction : InvMixColumn

